from ta_moler.cmd.egate.generictabcontent import GenericTabContent
from moler.exceptions import ParsingDone
from moler.helpers import convert_to_number
import re


class ScriptStatus(GenericTabContent):
    """Command script_status."""

    def __init__(self, connection, prompt=None, newline_chars=None, runner=None):
        """
        Command script_status.

        :param connection: moler connection to device, terminal when command is executed
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(ScriptStatus, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars,
                                           runner=runner)

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = "script_status"
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_script_status(line)
            except ParsingDone:
                pass
        return super(ScriptStatus, self).on_new_line(line, is_full_line)

    # 0   paused  1079        test.lua
    _re_script_status = re.compile(
        r"^(?P<ID>\d+)\s+(?P<STATE>\w+)\s+(?P<KBS>\d+)\s+(?P<LINE>\w*)\s+(?P<DESCRIPTION>\w+\.?\w+)")

    def _parse_script_status(self, line):
        if self._regex_helper.search_compiled(ScriptStatus._re_script_status, line):
            self.current_ret["id"] = convert_to_number(self._regex_helper.group('ID'))
            self.current_ret["state"] = self._regex_helper.group('STATE')
            self.current_ret["KBs"] = convert_to_number(self._regex_helper.group('KBS'))
            self.current_ret["line"] = self._regex_helper.group('LINE')
            self.current_ret["description"] = self._regex_helper.group('DESCRIPTION')
            raise ParsingDone


